INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42911, 'Exodus 19:17', 'Exodus', 19, 17, 'موسی هغوی د کمپ څخه دباندې راوستل چې د خدای سره ملاقات وکړي او هغوی د غره په لمنه کې ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_17.mp3', '', 1761754199, 1761754199),
(42912, 'Exodus 19:18', 'Exodus', 19, 18, 'د سینا ټول غر په لوګي کې پټ ؤ، ځکه چې څښتن په هغه باندې په اور کې راښکته شوی ؤ. دا لوګی د داش د لوګي په شان پورته کېده او ټول غر سخت لړزېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_18.mp3', '', 1761754199, 1761754199),
(42913, 'Exodus 19:19', 'Exodus', 19, 19, 'د سرني غږ نور هم لوړېده. موسی خبرې کولې او خدای هغه ته لکه د تندر په شان ځواب ورکاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_19.mp3', '', 1761754199, 1761754199),
(42914, 'Exodus 19:20', 'Exodus', 19, 20, 'څښتن د سینا د غره په سر راښکته شو او موسی یې د غره سرته راوغوښت. موسی وروخوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_20.mp3', '', 1761754199, 1761754199),
(42915, 'Exodus 19:21', 'Exodus', 19, 21, 'او څښتن هغه ته وویل: «ښکته لاړ شه او خلکو ته خبرداری ورکړه چې له حد څخه راوانه وړي چې راشي او ما وویني. که چېرې داسې وکړي، له هغوی څخه به ډېر کسان مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_21.mp3', '', 1761754199, 1761754199),
(42916, 'Exodus 19:22', 'Exodus', 19, 22, 'حتی کاهنان هم چې ماته نژدې راځي، باید ځانونه پاک کړي او که نه زه به هغوی ته هم سزا ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_22.mp3', '', 1761754199, 1761754199),
(42917, 'Exodus 19:23', 'Exodus', 19, 23, 'موسی څښتن ته وویل: «خلک د سینا غره ته نه شي راختلی، ځکه چې تا په خپله مونږ ته خبرداری راکړ چې د غره ګردچاپېره حد وټاکو او هغه غر سپېڅلی وګڼو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_23.mp3', '', 1761754199, 1761754199),
(42918, 'Exodus 19:24', 'Exodus', 19, 24, 'څښتن په ځواب کې وویل: «ښکته لاړ شه او هارون د ځان سره راوخېژوه. خو کاهنان او خلک باید د خپل حد څخه راتېر نه شي چې ماته راشي. که نه، نو زه به ورته سزا ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_24.mp3', '', 1761754199, 1761754199),
(42919, 'Exodus 19:25', 'Exodus', 19, 25, 'بیا موسی خلکو ته ورښکته شو او د څښتن خبرې یې ورته وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_25.mp3', '', 1761754199, 1761754199),
(42920, 'Psalms 27:1', 'Psalms', 27, 1, 'څښتن زما رڼا زما نجات دی نو بیا چا نه وېره وکړم؟ دی څښتن زما د ژوند ښه پناه ځای وېره نه کړم زه د چا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_1.mp3', '', 1761754199, 1761754199),
(42921, 'Psalms 27:2', 'Psalms', 27, 2, 'چې کړي کله بدکاران په ما حمله رقیبان او دښمنان چې کله هڅه زما د مرګ کړي تیندکونه خوري رالویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_2.mp3', '', 1761754199, 1761754199),
(42922, 'Psalms 27:3', 'Psalms', 27, 3, 'که لښکرې هم له ما نه شي چاپېرې زه به ونه کړمه وېره که جګړه زما په ضد هم شي روانه بیا به هم کوم توکل په څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_3.mp3', '', 1761754199, 1761754199),
(42923, 'Psalms 27:4', 'Psalms', 27, 4, 'زه د یو شي سوال کومه له څښتنه هغه دا دی چې یې غواړم چې ټول عمر د څښتن کور کې دېره شم چې زه ووینم ښېګڼې د څښتن او چې وکړمه طلب د هدایت یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_4.mp3', '', 1761754199, 1761754199),
(42924, 'Psalms 27:5', 'Psalms', 27, 5, 'د سختیو په وختونو کې به ماته پناه راکړي ما به وساتي په امن په خپل کور کې ما به وساتي خوندي په سر د لوړ ګټ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_5.mp3', '', 1761754199, 1761754199),
(42925, 'Psalms 27:6', 'Psalms', 27, 6, 'بریالی به شم په ټولو دښمنانو چې زما څخه چاپېر دي زه به ورکړم قربانۍ د ده په کور کې د خوشحالۍ په چیغو زه به وایمه سندرې د څښتن به کړم ثنا او صفت یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_6.mp3', '', 1761754199, 1761754199),
(42926, 'Psalms 27:7', 'Psalms', 27, 7, 'زه چې کله کړم فریاد نو ته یې واوره ای څښتنه مهربان شه په ما باندې او دعا مې کړه قبوله!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_7.mp3', '', 1761754199, 1761754199),
(42927, 'Psalms 27:8', 'Psalms', 27, 8, 'کله تا چې دي ویلي: «راشئ زما عبادت وکړئ» ما ځواب درته ویلی: «زه به درشم ای څښتنه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_8.mp3', '', 1761754199, 1761754199),
(42928, 'Psalms 27:9', 'Psalms', 27, 9, 'ته دې خپل مخ له ما نه مه اړوه ته په ما مه په قهرېږه ما مه شړه یمه زه ستا خدمتګار تل زما یې مددګار ای زما د نجات خدایه ته مې مه پرېږده او مه مې لېرې باسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_9.mp3', '', 1761754199, 1761754199),
(42929, 'Psalms 27:10', 'Psalms', 27, 10, 'که مې مور او پلار هم پرېږدي خو څښتن به ما قبول کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_10.mp3', '', 1761754199, 1761754199),
(42930, 'Psalms 27:11', 'Psalms', 27, 11, 'ماته خپله لاره وښایه څښتنه ما په سمه لاره بوځه ځکه ډېر مې دښمنان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_11.mp3', '', 1761754199, 1761754199),
(42931, 'Psalms 27:12', 'Psalms', 27, 12, 'ما د رقیبانو واک کې مه ورکوه راپورته شوي زما په ضد دي دروغجن شاهدان راکوي د تاوتریخوالي اخطارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_12.mp3', '', 1761754199, 1761754199),
(42932, 'Psalms 27:13', 'Psalms', 27, 13, 'زه باور لرم تر هغې به یم ژوندی ‎ چې خپل ژوند کې د څښتن نېکي وګورم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_13.mp3', '', 1761754199, 1761754199),
(42933, 'Psalms 27:14', 'Psalms', 27, 14, 'کړه توکل په څښتن اوسه مضبوطه او پرېږده زړه دې چې جرات پیدا کړي کړه توکل دې په څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms27_verse_14.mp3', '', 1761754199, 1761754199),
(42934, 'Ezekiel 35:1', 'Ezekiel', 35, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_1.mp3', '', 1761754199, 1761754199),
(42935, 'Ezekiel 35:2', 'Ezekiel', 35, 2, '«ای فاني انسانه، خپل مخ دې په ادوم کې د سعیر د غره خواته راواړوه او د هغه په ضد نبوت وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_2.mp3', '', 1761754199, 1761754199),
(42936, 'Ezekiel 35:3', 'Ezekiel', 35, 3, 'خلکو ته ووایه چې زه څښتن تعالی داسې وایم: ‹ای د سعیر غره، یمه زه ستا په ضد کړم به زه پورته خپل لاس ستا په ضد زه به کړم وران او ویجاړ تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_3.mp3', '', 1761754199, 1761754199),
(42937, 'Ezekiel 35:4', 'Ezekiel', 35, 4, 'په کنډوالو به زه بدل کړمه ښارونه ستا کړم به ستا وطن وران او ویجاړ بیا به پوه شې چې زه څښتن یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_4.mp3', '', 1761754199, 1761754199),
(42938, 'Ezekiel 35:5', 'Ezekiel', 35, 5, 'ته د اسراییلو تلپاتې دښمن یې او تا د جنګ په وخت کې د اسراییلو خلک پرېښودل چې ووژل شي یعنې د مصیبت په هغه وخت کې چې د خپلو ګناهونو له امله یې اخرنۍ سزا وليدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_5.mp3', '', 1761754199, 1761754199),
(42939, 'Ezekiel 35:6', 'Ezekiel', 35, 6, 'نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې ستا په قسمت کې به مرګ وي او د هغه نه خلاصېدلی نه شې. تا د وژنې څخه کرکه نه درلودله، نو په دې خاطر باید ووژل شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_6.mp3', '', 1761754199, 1761754199),
(42940, 'Ezekiel 35:7', 'Ezekiel', 35, 7, 'زه به د سعیر غر وران او ویجاړ کړم او هرڅوک چې په هغه کې تګ او راتګ کوي، هغه به ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_7.mp3', '', 1761754199, 1761754199),
(42941, 'Ezekiel 35:8', 'Ezekiel', 35, 8, 'زه به ستا غرونه د مړو څخه ډک کړم او ستا په غونډیو، درو او تنګيو کې به د خلکو هغه مړي پراته وي چې په جنګ کې وژل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_8.mp3', '', 1761754199, 1761754199),
(42942, 'Ezekiel 35:9', 'Ezekiel', 35, 9, 'زه به تا د تل دپاره وران او ویجاړ کړم او ستا په ښارونو کې به نور هېڅوک ونه اوسیږي. بیا به تاسو د ادوم خلک پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_9.mp3', '', 1761754199, 1761754199),
(42943, 'Ezekiel 35:10', 'Ezekiel', 35, 10, 'دا وطن زما دی، خو تا وویل چې د یهودا او اسراییلو دواړه قومونه او د هغوی وطنونه ستا دي او ته به هغه ونیسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_10.mp3', '', 1761754199, 1761754199),
(42944, 'Ezekiel 35:11', 'Ezekiel', 35, 11, 'نو زه څښتن تعالی په خپل ذات باندې قسم خورم چې زه به تاته د هغه قهر، حسادت او کرکې په خاطر چې زما د قوم سره دې لرله، محاکمه او سزا درکړم. نو بیا به زه خپل ځان اسراییلیانو ته ورښکاره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_11.mp3', '', 1761754199, 1761754199),
(42945, 'Ezekiel 35:12', 'Ezekiel', 35, 12, 'ته به هم پوه شې چې زه څښتن یم. ما څښتن ستا هغه د سپکاوۍ نه ډکې خبرې واورېدلې چې ودې ویل چې د اسراییلو غرونه ویجاړ شوي دي او هغه زمونږ خلکو ته راکړل شوي دي چې زمونږ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_12.mp3', '', 1761754199, 1761754199),
(42946, 'Ezekiel 35:13', 'Ezekiel', 35, 13, 'ما ستا هغه ډېرې خبرې او لافې چې زما په ضد دې کړې دي، اورېدلې دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_13.mp3', '', 1761754199, 1761754199),
(42947, 'Ezekiel 35:14', 'Ezekiel', 35, 14, 'څښتن تعالی داسې وایي: «زه به تا داسې وران او ویجاړ کړم چې ټوله نړۍ درباندې خوشحاله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_14.mp3', '', 1761754199, 1761754199),
(42948, 'Ezekiel 35:15', 'Ezekiel', 35, 15, 'لکه څنګه چې ته د اسراییلو په ورانېدلو باندې چې زما ملکیت دی خوشحاله شوې، نو زه به هم ستاسو سره همداسې چلند وکړم. د سعیر غر او د ادوم ټول وطن به وران او ویجاړ شي. بیا به اسراییلیان پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel35_verse_15.mp3', '', 1761754199, 1761754199),
(42949, 'Deuteronomy 2:1', 'Deuteronomy', 2, 1, 'په پای کې مونږ راوګرځېدلو او د څښتن د امر سره سم په هغې لارې باندې چې سرې بحیرې ته ځي، بېرته دښتې ته لاړو او ډېره موده د ادوم د غرنۍ سیمې په شاوخوا کې سرګردانه ګرځېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_1.mp3', '', 1761754199, 1761754199),
(42950, 'Deuteronomy 2:2', 'Deuteronomy', 2, 2, 'بیا څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_2.mp3', '', 1761754199, 1761754199),
(42951, 'Deuteronomy 2:3', 'Deuteronomy', 2, 3, '‹تاسو زیاته موده په هغو غونډیو کې سرګردانه وګرځېدلئ، اوس د شمال خواته لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_3.mp3', '', 1761754199, 1761754199),
(42952, 'Deuteronomy 2:4', 'Deuteronomy', 2, 4, 'په خلکو باندې دغه امر وکړه چې پام کوئ، ځکه چې تاسو به زر د ادوم د غرنۍ سیمې له لارې چې ستاسو د لېرې خپلوانو یعنې د عیسو د اولادې ځمکه ده، لاړ شئ. هغوی ستاسو څخه وېریږي، نو ډېر پام وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_4.mp3', '', 1761754199, 1761754199),
(42953, 'Deuteronomy 2:5', 'Deuteronomy', 2, 5, 'او د هغوی سره به جنګ نه کوئ، ځکه چې زه به د هغوی د ځمکې څخه تاسو ته یو متر مربع ځمکه هم در نه کړم. ما ادوم د عیسو اولادې ته ورکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_5.mp3', '', 1761754199, 1761754199),
(42954, 'Deuteronomy 2:6', 'Deuteronomy', 2, 6, 'تاسو کولای شئ چې د هغوی څخه خواړه او اوبه په بیه واخلئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_6.mp3', '', 1761754199, 1761754199),
(42955, 'Deuteronomy 2:7', 'Deuteronomy', 2, 7, 'یاد ساتئ چې خپل څښتن خدای څنګه تاسو ته په هر کار کې برکت درکړی دی. لکه څنګه به چې تاسو په دې پراخه دښته کې سرګردانه ګرځېدلئ، هغه په تاسو باندې پام کاوه. په دغو څلوېښتو کالو کې هغه ستاسو سره ؤ او هرڅه چې ستاسو په کار وو، هغه درته رسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_7.mp3', '', 1761754199, 1761754199),
(42956, 'Deuteronomy 2:8', 'Deuteronomy', 2, 8, 'مونږ د هغې سیمې په خوا کې تېر شو چې زمونږ د خپلوانو یعنې د عیسو د اولادې سیمه وه. هغه لاره مو پرېښودله چې د ایلت او عصیون جابر څخه مړې بحیرې ته ځي او شمال ختیځ خواته د موآب د دښتې په لور وګرځېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_8.mp3', '', 1761754199, 1761754199),
(42957, 'Deuteronomy 2:9', 'Deuteronomy', 2, 9, 'څښتن ماته وویل: ‹د موآب خلکو یعنې د لوط اولادې ته تکلیف ونه رسوئ او جنګ ورسره ونه کړئ. ما هغوی ته د عار سیمه ورکړې ده او تاسو ته به د هغوی د ځمکې څخه هېڅ یوه برخه در نه کړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_9.mp3', '', 1761754199, 1761754199),
(42958, 'Deuteronomy 2:10', 'Deuteronomy', 2, 10, 'د ډېرو غټو خلکو قوي نسل چې د ایمیانو په نوم یادېده په عار کې اوسېده. هغوی د عناقیانو په شان لوړ قدونه درلودل چې د ډېرو لوړ قدو خلکو بل نسل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_10.mp3', '', 1761754199, 1761754199),
(42959, 'Deuteronomy 2:11', 'Deuteronomy', 2, 11, 'هغوی هم د عناقیانو په شان د رفاییانو په نوم مشهور وو، خو موآبیانو هغوی د ایمیانو په نوم یادول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_11.mp3', '', 1761754199, 1761754199),
(42960, 'Deuteronomy 2:12', 'Deuteronomy', 2, 12, 'حوریان په ادوم کې اوسېدل، خو د عیسو اولادې هغوی وشړل. د هغوی قوم یې له منځه یووړ او په خپله هلته اوسېدل، لکه څنګه چې وروسته اسراییلیانو خپل دښمنان د هغې ځمکې څخه وشړل چې څښتن هغوی ته ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_12.mp3', '', 1761754199, 1761754199),
(42961, 'Deuteronomy 2:13', 'Deuteronomy', 2, 13, 'بیا لکه څنګه چې څښتن مونږ ته وویل، مونږ د زارد د خوړ څخه تېر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_13.mp3', '', 1761754199, 1761754199),
(42962, 'Deuteronomy 2:14', 'Deuteronomy', 2, 14, 'د هغه وخت نه چې مونږ د قادش برنیع څخه لاړو، اته دېرش کاله تېر شوي وو. لکه څنګه چې څښتن ویلي وو، د هغه نسل ټول جنګي خلک مړه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_14.mp3', '', 1761754199, 1761754199),
(42963, 'Deuteronomy 2:15', 'Deuteronomy', 2, 15, 'څښتن تر هغه وخته پورې د هغوی مخالفت کاوه، ترڅو چې ټول یې له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_15.mp3', '', 1761754199, 1761754199),
(42964, 'Deuteronomy 2:16', 'Deuteronomy', 2, 16, 'کله چې هغوی ټول مړه شول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_16.mp3', '', 1761754199, 1761754199),
(42965, 'Deuteronomy 2:17', 'Deuteronomy', 2, 17, 'څښتن مونږ ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_17.mp3', '', 1761754199, 1761754199),
(42966, 'Deuteronomy 2:18', 'Deuteronomy', 2, 18, '‹نن به تاسو د موآب د سیمې څخه د عار په لاره باندې تېر شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_18.mp3', '', 1761754199, 1761754199),
(42967, 'Deuteronomy 2:19', 'Deuteronomy', 2, 19, 'بیا به د عمونیانو ځمکې ته ورنژدې شئ چې د لوط اولاده ده. هغوی ته تکلیف مه رسوئ او جنګ ورسره مه کوئ. هغوی ته مې خپله ځمکه ورکړې ده او د هغې څخه به تاسو ته هېڅ در نه کړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_19.mp3', '', 1761754199, 1761754199),
(42968, 'Deuteronomy 2:20', 'Deuteronomy', 2, 20, 'دا سیمه هم د رفاییانو د خاورې په نوم مشهوره ده، یعنې د هغو خلکو په نوم چې هلته اوسېدلي وو. عمونیانو هغوی د زمزمیانو په نوم یادول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_20.mp3', '', 1761754199, 1761754199),
(42969, 'Deuteronomy 2:21', 'Deuteronomy', 2, 21, 'هغوی د عناقیانو په شان لوړ قدونه درلودل. هغوی ډېر وو او یو قوي نسل ؤ. خو څښتن هغوی تباه کړل، نو عمونیانو د هغوی خاوره ونیوله او هلته اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_21.mp3', '', 1761754199, 1761754199),
(42970, 'Deuteronomy 2:22', 'Deuteronomy', 2, 22, 'څښتن د ادومیانو یعنې د عیسو د اولادې دپاره چې د ادوم په غرنۍ سیمه کې اوسیږي همداسې کار کړی ؤ. هغه حوریان له منځه یووړل، نو ادومیانو د هغوی ځمکه ونیوله او هلته اوسېدل او تر اوسه پورې هلته ژوند کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_22.mp3', '', 1761754199, 1761754199),
(42971, 'Deuteronomy 2:23', 'Deuteronomy', 2, 23, 'په هغه ځمکه کې چې د مدیترانې د بحیرې په غاړه پرته وه، هغه خلک ځای په ځای شوي وو چې د کریت د جزیرې څخه وو. هغوی عویان چې د هغه ځای اصلي اوسېدونکي وو، له منځه وړي وو او د هغوی ټوله ځمکه یې په جنوب کې د غزې تر ښاره پورې نیولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_23.mp3', '', 1761754199, 1761754199),
(42972, 'Deuteronomy 2:24', 'Deuteronomy', 2, 24, 'کله چې مونږ د موآب څخه تېر شولو، څښتن مونږ ته وویل: ‹اوس روان شئ او د ارنون د سیند څخه تېر شئ. زه د حشبون پاچا سیحون د هغه د هېواد سره تاسو ته تسلیموم. حمله ورباندې وکړئ او د هغه هېواد ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_24.mp3', '', 1761754199, 1761754199),
(42973, 'Deuteronomy 2:25', 'Deuteronomy', 2, 25, 'له همدې ورځې څخه به ستاسو وېره د ټولو خلکو په زړونو کې چې په هرځای کې اوسیږي، واچوم. هرڅوک به ستاسو د نوم په اورېدلو سره د وېرې څخه لړزیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_25.mp3', '', 1761754199, 1761754199),
(42974, 'Deuteronomy 2:26', 'Deuteronomy', 2, 26, 'بیا ما د قدیموت د دښتې څخه د حشبون پاچا سیحون ته د سولې د لاندېني وړاندیز سره استازي ورولېږل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_26.mp3', '', 1761754199, 1761754199),
(42975, 'Deuteronomy 2:27', 'Deuteronomy', 2, 27, '‹مونږ پرېږدئ چې ستاسو د هېواد څخه تېر شو. مونږ به سیده لاړ شو او د لارې څخه به یو خوا بل خوا نه ځو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_27.mp3', '', 1761754199, 1761754199),
(42976, 'Deuteronomy 2:28', 'Deuteronomy', 2, 28, 'تاسو په مونږ باندې خواړه او اوبه خرڅ کړئ او مونږ به د هغو بیه درکړو. خو یوازې دا اجازه راکړئ چې ستاسو د هېواد په لاره تېر شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_28.mp3', '', 1761754199, 1761754199),
(42977, 'Deuteronomy 2:29', 'Deuteronomy', 2, 29, 'ترڅو د اردن د سیند څخه هغې ځمکې ته واوړو چې خپل څښتن خدای یې راکوي. د عیسو اولادې چې په ادوم کې اوسیږي او موآبیانو چې په عار کې اوسیږي، مونږ ته اجازه راکړه چې د هغوی د سیمې څخه تېر شو.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_29.mp3', '', 1761754199, 1761754199),
(42978, 'Deuteronomy 2:30', 'Deuteronomy', 2, 30, 'خو سیحون پاچا نه پرېښودلو چې د هغه د هېواد په لاره تېر شو. زمونږ څښتن خدای د هغه زړه سخت کړی ؤ او هغه یې سرزوره کړی ؤ ترڅو مونږ وکولای شو هغه ته ماتې ورکړو او د هغه سیمه ونیسو چې تر اوسه پورې زمونږ سره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_30.mp3', '', 1761754199, 1761754199),
(42979, 'Deuteronomy 2:31', 'Deuteronomy', 2, 31, 'بیا څښتن ماته وویل: ‹ګوره، ما سیحون پاچا او د هغه خلک ستاسو په وړاندې کمزوري کړي دي، لاړ شئ او د هغه خاوره ونیسئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_31.mp3', '', 1761754199, 1761754199),
(42980, 'Deuteronomy 2:32', 'Deuteronomy', 2, 32, 'بیا سیحون د خپلو ټولو کسانو سره راووت چې د یاهص ښار ته نژدې زمونږ سره وجنګیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_32.mp3', '', 1761754199, 1761754199),
(42981, 'Deuteronomy 2:33', 'Deuteronomy', 2, 33, 'خو زمونږ څښتن خدای هغه مونږ ته په لاس راکړ او مونږ هغه، د هغه زامن او د هغه ټول کسان ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_33.mp3', '', 1761754199, 1761754199),
(42982, 'Deuteronomy 2:34', 'Deuteronomy', 2, 34, 'په همدې وخت کې مونږ هر یو ښار ونیوه او هغه مو له منځه یووړ او ټول نارینه، ښځې او ماشومان مو ووژل. هېڅوک مو ژوندی پرېنښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_34.mp3', '', 1761754199, 1761754199),
(42983, 'Deuteronomy 2:35', 'Deuteronomy', 2, 35, 'خو مونږ د هغوی حیوانات یووړل او ښارونه مو ورته لوټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_35.mp3', '', 1761754199, 1761754199),
(42984, 'Deuteronomy 2:36', 'Deuteronomy', 2, 36, 'زمونږ څښتن خدای مونږ پرېښودلو چې ټول ښارونه د عروعیر څخه نیولې چې د ارنون د درې په غاړه پروت دی او هغه ښار چې د درې په منځ کې دی، تر جلعاد پورې ونیسو. د هېڅ یو ښار دېوالونو زمونږ په وړاندې مقاومت نه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_36.mp3', '', 1761754199, 1761754199),
(42985, 'Deuteronomy 2:37', 'Deuteronomy', 2, 37, 'خو مونږ د عمونیانو سیمې یا د یبوق د سیند غاړې ته یا د غرنۍ سیمې ښارونو ته یا داسې بل ځای ته ورنژدې نه شو چې زمونږ څښتن خدای هغو ځایونو ته د ورتګ څخه منع کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy2_verse_37.mp3', '', 1761754199, 1761754199),
(42986, 'Isaiah 9:1', 'Isaiah', 9, 1, 'خو هغه خلک چې په کړاو کې دي، دا تیاره د تل دپاره نه پاتې کیږي. پخوا څښتن د زبولون او نفتالي سیمې سپکې او رسوا کړې، خو په راتلونکې کې به دا سیمې د مدیترانې له بحیرې نیولې د اردن د سیند تر بلې غاړې او حتی جلیل پورې چې پردي قومونه په کې اوسیږي د شان او شوکت خاوند کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_1.mp3', '', 1761754199, 1761754199),
(42987, 'Isaiah 9:2', 'Isaiah', 9, 2, 'هغه خلک چې تیارو کې ګرځېدل هغوی ولیده یوه لویه رڼا چې اوسېدل توره تیاره ځمکه کې هغه خلک په هغو خلکو اوس رڼا ځلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_2.mp3', '', 1761754199, 1761754199),
(42988, 'Isaiah 9:3', 'Isaiah', 9, 3, 'ای څښتنه، تا لوی کړی دی دا قوم وربخښلې خوشحالي ده تا دې قوم ته تا چې څه کړي دي هغوی پرې خوشحالي کوي لکه کړي خلک خوشحالي چې د فصلونو د رېبلو وخت کې یا کله خلک چې وېشي د غنیمت مالونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_3.mp3', '', 1761754199, 1761754199),
(42989, 'Isaiah 9:4', 'Isaiah', 9, 4, 'د خوشحالۍ دلیل یې دا ؤ چې تا مات کړلو د دوی د اوږو جغ تا کړله هغه لښته ماته چې وهلې یې اوږې له هغو تا ورکړه ماته هغه قوم ته چې کاوه ظلم یې د ستا په خلکو لکه لښکر د مدیانیانو چې مات کړی ؤ تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_4.mp3', '', 1761754199, 1761754199),
(42990, 'Isaiah 9:5', 'Isaiah', 9, 5, 'ښوروي چې بوټان ځمکه د لښکرو یرغلګرو او چې کالي یې دي ککړ په وینو هغه ټول به شي خاشاک د سوځېدو د اور دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_5.mp3', '', 1761754199, 1761754199),
(42991, 'Isaiah 9:6', 'Isaiah', 9, 6, 'زېږېدلی زمونږ دپاره یو ماشوم دی مونږ ته یو زوی دی راکړل شوی وي به بار د حکومت د هغه په اوږو هغه یادیږي به په دې نومونو: «عجیب مشاور»، «قادر خدای» «ابدي پلار» او «د سولې شاهزاده»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_6.mp3', '', 1761754199, 1761754199),
(42992, 'Isaiah 9:7', 'Isaiah', 9, 7, 'هغه به کښېني د داود په تخت واک او قدرت د پاچاهۍ به یې د وخت په تېرېدو زیاتیږي پاچاهي به د هغه وي تل په امن بنیاد به ټینګ د پاچاهۍ وي د هغه په عدالت او انصاف له همدا اوس نه تر ابده پورې مطلق قادر څښتن به وکړي دا کار په خپل غیرت باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_7.mp3', '', 1761754199, 1761754199),
(42993, 'Isaiah 9:8', 'Isaiah', 9, 8, 'څښتن د اسراییلو قوم یعنې د یعقوب اولادې ته خبرداری ورکړ چې هغوی ته به سزا ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_8.mp3', '', 1761754199, 1761754199),
(42994, 'Isaiah 9:9', 'Isaiah', 9, 9, 'هغه ټول اسراییلیان او هغه ټول خلک چې د سامرې په ښار کې اوسیږي، هغوی به پوه شي چې دا کار هغه کړی دی، خو هغوی مغرور او کبرجن دي. هغوی وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_9.mp3', '', 1761754199, 1761754199),
(42995, 'Isaiah 9:10', 'Isaiah', 9, 10, '«د خښتو ودانۍ راغورځېدلې دي، خو مونږ به د هغو په ځای له توږل شویو تیږو ودانۍ جوړې کړو. د انځرو د لرګیو کوم تیران چې مات شوي دي د هغو په ځای به د سبر د لرګیو تیران جوړ کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_10.mp3', '', 1761754199, 1761754199),
(42996, 'Isaiah 9:11', 'Isaiah', 9, 11, 'په دې خاطر څښتن به د رزین دښمنان راوپاروي چې په اسراییلو باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_11.mp3', '', 1761754199, 1761754199),
(42997, 'Isaiah 9:12', 'Isaiah', 9, 12, 'سوریې له ختیځې خوا او فلسطین له لوېدیځې خوا خپلې خولې خلاصې نیولې چې اسراییل ژوندي تېر کړي. خو بیاهم د څښتن قهر لا نه دی سوړ شوی او د هغه لاس لا تر اوسه د سزا ورکولو دپاره اوچت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_12.mp3', '', 1761754199, 1761754199),
(42998, 'Isaiah 9:13', 'Isaiah', 9, 13, 'که څه هم مطلق قادر څښتن د اسراییلو خلک وهلي دي، خو هغوی لا هم توبه نه ده ویستلې او هغه ته یې بېرته رجوع نه ده کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_13.mp3', '', 1761754199, 1761754199),
(42999, 'Isaiah 9:14', 'Isaiah', 9, 14, 'په دې خاطر به څښتن په یوه ورځ کې د اسراییلو مشرانو او خلکو ته سزا ورکړي یعنې د هغوی سرونه او لکۍ به پرې کړي. د خرما څانګې چې د عزت نښه ده او لوخې چې د عاجزۍ نښه ده، دواړه به پرې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_14.mp3', '', 1761754199, 1761754199),
(43000, 'Isaiah 9:15', 'Isaiah', 9, 15, 'سپین ږیري او عزتمن خلک سر او هغه پیغمبران چې د دروغو تعلیم ورکوي، هغه لکۍ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_15.mp3', '', 1761754199, 1761754199),
(43001, 'Isaiah 9:16', 'Isaiah', 9, 16, 'د دې خلکو لارښوونکي هغوی بې لارې کړي دي او د تباهۍ خواته یې بیولي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_16.mp3', '', 1761754199, 1761754199),
(43002, 'Isaiah 9:17', 'Isaiah', 9, 17, 'نو څښتن به په ځوانانو، حتی په یتیمانو او کونډو باندې هم رحم ونه کړي، ځکه چې ټول خلک بې ایمانه او بدکاره شوي دي او هغوی چې هرڅه وایي هغه احمقانه دي. خو بیاهم د څښتن قهر لا نه دی سوړ شوی، د هغه لاس لا تر اوسه د سزا ورکولو دپاره اوچت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_17.mp3', '', 1761754199, 1761754199),
(43003, 'Isaiah 9:18', 'Isaiah', 9, 18, 'د خلکو بده کړنه د هغه اور په شان بلیږي چې اغزي او کرکڼې له منځه وړي. هغه د ځنګل د اور په شان ده چې لوګی یې هوا ته پورته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_18.mp3', '', 1761754199, 1761754199),
(43004, 'Isaiah 9:19', 'Isaiah', 9, 19, 'ځکه چې مطلق قادر څښتن په قهر دی، د هغه سزا د هغه اور په شان ده چې ټول وطن سوځوي او خلک تباه کوي او څوک په خپل ورور باندې زړه نه سوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_19.mp3', '', 1761754199, 1761754199),
(43005, 'Isaiah 9:20', 'Isaiah', 9, 20, 'خلک د خوړلو دپاره هرڅه په لاس راوړي، خو وږي پاتې کیږي او نه مړیږي. د ډېرې لوږې له امله حتی هغوی خپل ماشومان هم خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_20.mp3', '', 1761754199, 1761754199),
(43006, 'Isaiah 9:21', 'Isaiah', 9, 21, 'د منسي او افرایم خلک په یو بل باندې حمله کوي او بیا دواړه یوځای کیږي او په ګډه په یهودا باندې حمله کوي. خو بیاهم د څښتن قهر لا نه دی سوړ شوی، د هغه لاس لا تر اوسه پورې د سزا ورکولو دپاره اوچت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah9_verse_21.mp3', '', 1761754199, 1761754199),
(43007, 'Isaiah 39:1', 'Isaiah', 39, 1, 'په همدې وخت کې د بابل پاچا د بلدان زوی مرودک بلدان خبر شو چې حزقیا پاچا ناروغ ؤ او اوس روغ شوی دی، نو هغه د خپلو استازو په لاس حزقیا ته لیکونه او یو سوغات ورولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_1.mp3', '', 1761754199, 1761754199),
(43008, 'Isaiah 39:2', 'Isaiah', 39, 2, 'حزقیا استازو ته تود هرکلی ووایه او هغوی ته یې د خپلو شتمنېو تحویلخانې، یعنې خپل سپین او سره زر، خپل خوشبویه تېل او عطرونه او خپل ټول عسکري سامان وروښودل. د هغه په ماڼۍ یا پاچاهۍ کې داسې شی نه ؤ چې هغوی ته یې نه وي ښودلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_2.mp3', '', 1761754199, 1761754199),
(43009, 'Isaiah 39:3', 'Isaiah', 39, 3, 'بیا اشعیا نبي حزقیا پاچا ته ورغی او پوښتنه یې ترې وکړه: «دا خلک د کوم ځای څخه راغلي وو او تاته یې څه وویل؟» حزقیا ځواب ورکړ: «هغوی د یو ډېر لېرې وطن یعنې د بابل څخه راغلي وو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_3.mp3', '', 1761754199, 1761754199),
(43010, 'Isaiah 39:4', 'Isaiah', 39, 4, 'اشعیا پوښتنه وکړه: «ستا په ماڼۍ کې هغوی څه ولیدل؟» حزقیا ځواب ورکړ: «هغوی هرڅه ولیدل. په تحویلخانو کې داسې شی نه ؤ چې هغوی ته مې نه وي ښودلی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_4.mp3', '', 1761754199, 1761754199);